import { createServer } from "node:http";
import { buildInvoice } from "../invoices/build.js";
import { memoryStore } from "../store/memory.js";

const store = memoryStore();

export const server = createServer(async (req, res) => {
  if (req.method !== "POST" || req.url !== "/invoices") return res.writeHead(404).end();
  let body = "";
  for await (const chunk of req) body += chunk;
  try {
    const invoice = buildInvoice(JSON.parse(body), { store });
    res.writeHead(201, { "content-type": "application/json" }).end(JSON.stringify(invoice));
  } catch (error) {
    res.writeHead(422, { "content-type": "application/json" }).end(JSON.stringify({ error: error.message, problems: error.problems ?? [] }));
  }
});

if (process.argv[1] === new URL(import.meta.url).pathname) server.listen(process.env.PORT ?? 3000);

// Repeated SKUs merge into one line so quantity tiers see the combined quantity.
export function normalizeLines(lines) {
  const bySku = new Map();
  for (const line of lines) bySku.set(line.sku, (bySku.get(line.sku) ?? 0) + line.qty);
  return [...bySku].map(([sku, qty]) => ({ sku, qty }));
}

import { REGIONS } from "../tax/regions.js";
import { digits } from "../money/currency.js";

export function validateOrder(order) {
  const problems = [];
  if (!order.customerId) problems.push("customerId is required");
  if (!Array.isArray(order.lines) || order.lines.length === 0) problems.push("at least one line is required");
  if (!(order.shipTo in REGIONS)) problems.push(`unknown region ${order.shipTo}`);
  try { digits(order.currency); } catch { problems.push(`unsupported currency ${order.currency}`); }
  for (const [i, line] of (order.lines ?? []).entries()) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) problems.push(`line ${i}: qty must be a positive integer`);
  }
  if (problems.length) throw Object.assign(new Error("invalid order"), { problems });
  return order;
}

