export function nextInvoiceNumber(store, issuedAt) {
  const year = issuedAt.getUTCFullYear();
  const seq = store.increment(`invoice-seq-${year}`);
  return `INV-${year}-${String(seq).padStart(6, "0")}`;
}

export function memoryStore() {
  const tables = new Map();
  const counters = new Map();
  return {
    save(table, id, row) {
      if (!tables.has(table)) tables.set(table, new Map());
      tables.get(table).set(id, structuredClone(row));
    },
    get: (table, id) => tables.get(table)?.get(id) ?? null,
    increment(key) {
      const next = (counters.get(key) ?? 0) + 1;
      counters.set(key, next);
      return next;
    },
  };
}

const PRODUCTS = {
  "seat-pro": { currency: "USD", category: "software", tiers: [[1, 30], [10, 27], [50, 24]] },
  "seat-team": { currency: "USD", category: "software", tiers: [[1, 12], [25, 10]] },
  "onboarding": { currency: "USD", category: "services", tiers: [[1, 1500]] },
  "hardware-key": { currency: "EUR", category: "goods", tiers: [[1, 45], [100, 39]] },
};

export function product(sku) {
  const found = PRODUCTS[sku];
  if (!found) throw new Error(`unknown sku ${sku}`);
  return found;
}

export function unitPrice(sku, qty) {
  const { tiers } = product(sku);
  let price = tiers[0][1];
  for (const [minQty, tierPrice] of tiers) if (qty >= minQty) price = tierPrice;
  return price;
}

import { roundMinor, ROUNDING } from "../money/round.js";

// Order: line-level promos first, then at most one order-level coupon, never below the floor.
export function applyLineDiscounts(line, promos) {
  const promo = promos.find((p) => p.sku === line.sku && line.qty >= (p.minQty ?? 1));
  if (!promo) return line;
  const off = roundMinor((line.amountMinor * promo.percent) / 100, ROUNDING.DOWN);
  return { ...line, amountMinor: line.amountMinor - off, promo: promo.code };
}

export function applyCoupon(subtotalMinor, coupon, floorMinor = 0) {
  if (!coupon) return { totalMinor: subtotalMinor, coupon: null };
  const off = coupon.kind === "percent" ? roundMinor((subtotalMinor * coupon.value) / 100) : coupon.valueMinor;
  return { totalMinor: Math.max(floorMinor, subtotalMinor - off), coupon: coupon.code };
}

import { roundMinor } from "../money/round.js";
import { region } from "./regions.js";

// Per-line regions round each line's tax; others round once on the taxable sum.
export function computeTax(lines, regionCode) {
  const r = region(regionCode);
  const taxable = lines.filter((line) => !r.exempt.includes(line.category));
  if (r.perLine) return taxable.reduce((sum, line) => sum + roundMinor(line.amountMinor * r.rate, r.rounding), 0);
  const base = taxable.reduce((sum, line) => sum + line.amountMinor, 0);
  return roundMinor(base * r.rate, r.rounding);
}

import { roundMinor } from "./round.js";

const MINOR_DIGITS = { USD: 2, EUR: 2, GBP: 2, JPY: 0, BHD: 3 };
const FX_TO_USD = { USD: 1, EUR: 1.08, GBP: 1.27, JPY: 0.0067, BHD: 2.65 };

export function digits(currency) {
  if (!(currency in MINOR_DIGITS)) throw new Error(`unsupported currency ${currency}`);
  return MINOR_DIGITS[currency];
}

export const toMinor = (amount, currency, mode) => roundMinor(amount * 10 ** digits(currency), mode);
export const fromMinor = (minor, currency) => minor / 10 ** digits(currency);

export function convertMinor(minor, from, to, mode) {
  if (from === to) return minor;
  const usd = fromMinor(minor, from) * FX_TO_USD[from];
  return toMinor(usd / FX_TO_USD[to], to, mode);
}

import { ROUNDING } from "../money/round.js";

export const REGIONS = {
  "US-CA": { rate: 0.0725, exempt: ["services"], rounding: ROUNDING.HALF_UP, perLine: false },
  "US-OR": { rate: 0, exempt: [], rounding: ROUNDING.HALF_UP, perLine: false },
  "DE": { rate: 0.19, exempt: [], rounding: ROUNDING.HALF_EVEN, perLine: true },
  "GB": { rate: 0.2, exempt: ["software"], rounding: ROUNDING.HALF_UP, perLine: true },
};

export function region(code) {
  const found = REGIONS[code];
  if (!found) throw new Error(`no tax region ${code}`);
  return found;
}

export const ROUNDING = { HALF_UP: "half-up", HALF_EVEN: "half-even", DOWN: "down" };

export function roundMinor(value, mode = ROUNDING.HALF_UP) {
  const floor = Math.floor(value);
  const fraction = value - floor;
  if (mode === ROUNDING.DOWN) return floor;
  if (Math.abs(fraction - 0.5) < 1e-9) {
    if (mode === ROUNDING.HALF_EVEN) return floor % 2 === 0 ? floor : floor + 1;
    return floor + 1;
  }
  return Math.round(value);
}

